def match_batch(invoices: list[dict], payments: list[dict]) -> list[tuple[str, str]]:
    """Return (invoice_id, payment_id) pairs matching on ref_id and amount_cents."""
    payment_index = {(p['ref_id'], p['amount_cents']): p['payment_id'] for p in payments}
    matches = []
    for inv in invoices:
        key = (inv['ref_id'], inv['amount_cents'])
        if key in payment_index:
            matches.append((inv['invoice_id'], payment_index[key]))
    return matches
